Shell HTTP <pre><code>curl -X POST -H "Content-Type: application/json" http://localhost:8545 --data '{"jsonrpc": "2.0", "id": 42, "method": "admin_ecbp1100Status", "params": []}'
</code></pre> Shell WebSocket <pre><code>wscat -c ws://localhost:8546 -x '{"jsonrpc": "2.0", "id": 1, "method": "admin_ecbp1100Status", "params": []}'
</code></pre> Javascript Console <pre><code>admin.ecbp1100Status();
</code></pre> Source code <p> <pre><code>func (api *AdminAPI) Ecbp1100Status() ECBP1100Status {
    config := api.eth.blockchain.Config()
    head := api.eth.blockchain.CurrentBlock().Number
    nodeSwitch := api.eth.blockchain.IsArtificialFinalityEnabled()
    return ECBP1100Status{Enabled: nodeSwitch &amp;&amp; config.IsEnabled(config.GetECBP1100Transition, head), NodeSwitch: nodeSwitch, ActivatedAtBlock: config.GetECBP1100Transition(), DefaultDisabledAtBlock: config.GetECBP1100DeactivateTransition(), Head: head.Uint64()}
}// Ecbp1100Status reports the ECBP-1100 (MESS) state at the current head and
// changes nothing.
//
// Ecbp1100 above answers a similar question by first assigning the activation
// block it is passed, so it cannot be used to observe a running node. This
// exists so that state can be read without altering it.
</code></pre> View on GitHub → </p>

Shell HTTP <pre><code>curl -X POST -H "Content-Type: application/json" http://localhost:8545 --data '{"jsonrpc": "2.0", "id": 42, "method": "admin_exportChain", "params": [&lt;file&gt;, &lt;first&gt;, &lt;last&gt;]}'
</code></pre> Shell WebSocket <pre><code>wscat -c ws://localhost:8546 -x '{"jsonrpc": "2.0", "id": 1, "method": "admin_exportChain", "params": [&lt;file&gt;, &lt;first&gt;, &lt;last&gt;]}'
</code></pre> Javascript Console <pre><code>admin.exportChain(file,first,last);
</code></pre> Source code <p> <pre><code>func (api *AdminAPI) ExportChain(file string, first *uint64, last *uint64) (bool, error) {
    if first == nil &amp;&amp; last != nil {
        return false, errors.New("last cannot be specified without first")
    }
    if first != nil &amp;&amp; last == nil {
        head := api.eth.BlockChain().CurrentHeader().Number.Uint64()
        last = &amp;head
    }
    if _, err := os.Stat(file); err == nil {
        return false, errors.New("location would overwrite an existing file")
    }
    out, err := os.OpenFile(file, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0644)
    if err != nil {
        return false, err
    }
    defer out.Close()
    var writer io.Writer = out
    if strings.HasSuffix(file, ".gz") {
        writer = gzip.NewWriter(writer)
        defer writer.(*gzip.Writer).Close()
    }
    if first != nil {
        if err := api.eth.BlockChain().ExportN(writer, *first, *last); err != nil {
            return false, err
        }
    } else if err := api.eth.BlockChain().Export(writer); err != nil {
        return false, err
    }
    return true, nil
}// ExportChain exports the current blockchain into a local file,
// or a range of blocks if first and last are non-nil.
</code></pre> View on GitHub → </p>

Shell HTTP <pre><code>curl -X POST -H "Content-Type: application/json" http://localhost:8545 --data '{"jsonrpc": "2.0", "id": 42, "method": "admin_importChain", "params": [&lt;file&gt;]}'
</code></pre> Shell WebSocket <pre><code>wscat -c ws://localhost:8546 -x '{"jsonrpc": "2.0", "id": 1, "method": "admin_importChain", "params": [&lt;file&gt;]}'
</code></pre> Javascript Console <pre><code>admin.importChain(file);
</code></pre> Source code <p> <pre><code>func (api *AdminAPI) ImportChain(file string) (bool, error) {
    in, err := os.Open(file)
    if err != nil {
        return false, err
    }
    defer in.Close()
    var reader io.Reader = in
    if strings.HasSuffix(file, ".gz") {
        if reader, err = gzip.NewReader(reader); err != nil {
            return false, err
        }
    }
    stream := rlp.NewStream(reader, 0)
    blocks, index := make([ // ImportChain imports a blockchain from a local file.
    ]*types.Block, 0, 2500), 0
    for batch := 0; ; batch++ {
        for len(blocks) &lt; cap(blocks) {
            block := new(types.Block)
            if err := stream.Decode(block); err == io.EOF {
                break
            } else if err != nil {
                return false, fmt.Errorf("block %d: failed to parse: %v", index, err)
            }
            if block.NumberU64() == 0 {
                continue
            }
            blocks = append(blocks, block)
            index++
        }
        if len(blocks) == 0 {
            break
        }
        if hasAllBlocks(api.eth.BlockChain(), blocks) {
            blocks = blocks[:0]
            continue
        }
        if _, err := api.eth.BlockChain().InsertChain(blocks); err != nil {
            return false, fmt.Errorf("batch %d: failed to insert: %v", batch, err)
        }
        blocks = blocks[:0]
    }
    return true, nil
}
</code></pre> View on GitHub → </p>

Shell HTTP <pre><code>curl -X POST -H "Content-Type: application/json" http://localhost:8545 --data '{"jsonrpc": "2.0", "id": 42, "method": "admin_maxPeers", "params": [&lt;n&gt;]}'
</code></pre> Shell WebSocket <pre><code>wscat -c ws://localhost:8546 -x '{"jsonrpc": "2.0", "id": 1, "method": "admin_maxPeers", "params": [&lt;n&gt;]}'
</code></pre> Javascript Console <pre><code>admin.maxPeers(n);
</code></pre> Source code <p> <pre><code>func (api *AdminAPI) MaxPeers(n int) (bool, error) {
    api.eth.handler.maxPeers = n
    api.eth.p2pServer.MaxPeers = n
    for i := api.eth.handler.peers.len(); i &gt; n; i = api.eth.handler.peers.len() {
        p := api.eth.handler.peers.WorstPeer()
        if p == nil {
            break
        }
        api.eth.handler.removePeer(p.ID())
    }
    return true, nil
}// MaxPeers sets the maximum peer limit for the protocol manager and the p2p server.
</code></pre> View on GitHub → </p>

