Shell WebSocket <pre><code>wscat -c ws://localhost:8546 -x '{"jsonrpc": "2.0", "id": 1, "method": "admin_subscribe", "params": ["peerEvents"]}'
</code></pre> Source code <p> <pre><code>func (api *adminAPI) PeerEvents(ctx context.Context) (*rpc.Subscription, error) {
    server := api.node.Server()
    if server == nil {
        return nil, ErrNodeStopped
    }
    notifier, supported := rpc.NotifierFromContext(ctx)
    if !supported {
        return nil, rpc.ErrNotificationsUnsupported
    }
    rpcSub := notifier.CreateSubscription()
    go func() {
        events := make(chan *p2p.PeerEvent)
        sub := server.SubscribeEvents(events)
        defer sub.Unsubscribe()
        for {
            select {
            case event := &lt;-events:
                notifier.Notify(rpcSub.ID, event)
            case &lt;-sub.Err():
                return
            case &lt;-rpcSub.Err():
                return
            case &lt;-notifier.Closed():
                return
            }
        }
    }()
    return rpcSub, nil
}// PeerEvents creates an RPC subscription which receives peer events from the
// node's p2p.Server
</code></pre> View on GitHub → </p>

