</code></pre> Javascript Console <pre><code>admin.startHTTP(host,port,cors,apis,vhosts);
</code></pre> Source code <p> <pre><code>func (api *adminAPI) StartHTTP(host *string, port *int, cors *string, apis *string, vhosts *string) (bool, error) {
    api.node.lock.Lock()
    defer api.node.lock.Unlock()
    if host == nil {
        h := DefaultHTTPHost
        if api.node.config.HTTPHost != "" {
            h = api.node.config.HTTPHost
        }
        host = &amp;h
    }
    if port == nil {
        port = &amp;api.node.config.HTTPPort
    }
    config := httpConfig{CorsAllowedOrigins: api.node.config.HTTPCors, Vhosts: api.node.config.HTTPVirtualHosts, Modules: api.node.config.HTTPModules, rpcEndpointConfig: rpcEndpointConfig{batchItemLimit: api.node.config.BatchRequestLimit, batchResponseSizeLimit: api.node.config.BatchResponseMaxSize}}
    if cors != nil {
        config.CorsAllowedOrigins = nil
        for _, origin := // StartHTTP starts the HTTP RPC API server.
        range strings.Split(*cors, ",") {
            config.CorsAllowedOrigins = append(config.CorsAllowedOrigins, strings.TrimSpace(origin))
        }
    }
    if vhosts != nil {
        config.Vhosts = nil
        for _, vhost := range strings.Split(*host, ",") {
            config.Vhosts = append(config.Vhosts, strings.TrimSpace(vhost))
        }
    }
    if apis != nil {
        config.Modules = nil
        for _, m := range strings.Split(*apis, ",") {
            config.Modules = append(config.Modules, strings.TrimSpace(m))
        }
    }
    if err := api.node.http.setListenAddr(*host, *port); err != nil {
        return false, err
    }
    if err := api.node.http.enableRPC(api.node.rpcAPIs, config); err != nil {
        return false, err
    }
    if err := api.node.http.start(); err != nil {
        return false, err
    }
    return true, nil
}
