Shell HTTP <pre><code>curl -X POST -H "Content-Type: application/json" http://localhost:8545 --data '{"jsonrpc": "2.0", "id": 42, "method": "debug_accountRange", "params": [&lt;blockNrOrHash&gt;, &lt;start&gt;, &lt;maxResults&gt;, &lt;nocode&gt;, &lt;nostorage&gt;, &lt;incompletes&gt;]}'
</code></pre> Shell WebSocket <pre><code>wscat -c ws://localhost:8546 -x '{"jsonrpc": "2.0", "id": 1, "method": "debug_accountRange", "params": [&lt;blockNrOrHash&gt;, &lt;start&gt;, &lt;maxResults&gt;, &lt;nocode&gt;, &lt;nostorage&gt;, &lt;incompletes&gt;]}'
</code></pre> Javascript Console <pre><code>debug.accountRange(blockNrOrHash,start,maxResults,nocode,nostorage,incompletes);
</code></pre> Source code <p> <pre><code>func (api *DebugAPI) AccountRange(blockNrOrHash rpc.BlockNumberOrHash, start hexutil.Bytes, maxResults int, nocode, nostorage, incompletes bool) (state.Dump, error) {
    var stateDb *state.StateDB
    var err error
    if number, ok := blockNrOrHash.Number(); ok {
        if number == rpc.PendingBlockNumber {
            _, stateDb = api.eth.miner.Pending()
            if stateDb == nil {
                return state.Dump{}, errors.New("pending state is not available")
            }
        } else {
            var header *types.Header
            switch number {
            case rpc.LatestBlockNumber:
                header = api.eth.blockchain.CurrentBlock()
            case rpc.FinalizedBlockNumber:
                header = api.eth.blockchain.CurrentFinalBlock()
            case rpc.SafeBlockNumber:
                header = api.eth.blockchain.CurrentSafeBlock()
            default:
                block := api.eth.blockchain.GetBlockByNumber(uint64(number))
                if block == nil {
                    return state.Dump{}, fmt.Errorf("block #%d not found", number)
                }
                header = block.Header()
            }
            if header == nil {
