</code></pre> Source code <p> <pre><code>func (api *API) IntermediateRoots(ctx context.Context, hash common.Hash, config *TraceConfig) ([ // IntermediateRoots executes a block (bad- or canon- or side-), and returns a list
// of intermediate roots: the stateroot after each transaction.
]common.Hash, error) {
    block, _ := api.blockByHash(ctx, hash)
    if block == nil {
        block = rawdb.ReadBadBlock(api.backend.ChainDb(), hash)
    }
    if block == nil {
        return nil, fmt.Errorf("block %#x not found", hash)
    }
    if block.NumberU64() == 0 {
        return nil, errors.New("genesis is not traceable")
    }
    parent, err := api.blockByNumberAndHash(ctx, rpc.BlockNumber(block.NumberU64()-1), block.ParentHash())
    if err != nil {
        return nil, err
    }
    reexec := defaultTraceReexec
    if config != nil &amp;&amp; config.Reexec != nil {
        reexec = *config.Reexec
    }
    statedb, release, err := api.backend.StateAtBlock(ctx, parent, reexec, nil, true, false)
    if err != nil {
        return nil, err
    }
    defer release()
    var (
        roots           []common.Hash
        signer          = types.MakeSigner(api.backend.ChainConfig(), block.Number(), block.Time())
        chainConfig     = api.backend.ChainConfig()
        vmctx           = core.NewEVMBlockContext(block.Header(), api.chainContext(ctx), nil)
        deleteEmptyObjects  = api.backend.ChainConfig().IsEnabled(api.backend.ChainConfig().GetEIP161dTransition, block.Number())
    )
    for i, tx := range block.Transactions() {
        if err := ctx.Err(); err != nil {
            return nil, err
        }
        var (
            msg, _      = core.TransactionToMessage(tx, signer, block.BaseFee())
            txContext   = core.NewEVMTxContext(msg)
            vmenv       = vm.NewEVM(vmctx, txContext, statedb, chainConfig, vm.Config{})
        )
        statedb.SetTxContext(tx.Hash(), i)
        if _, err := core.ApplyMessage(vmenv, msg, new(core.GasPool).AddGas(msg.GasLimit)); err != nil {
            log.Warn("Tracing intermediate roots did not complete", "txindex", i, "txhash", tx.Hash(), "err", err)
            return roots, nil
        }
        roots = append(roots, statedb.IntermediateRoot(deleteEmptyObjects))
    }
    return roots, nil
}
