</code></pre> Source code <p> <pre><code>func (api *API) TraceChain(ctx context.Context, start, end rpc.BlockNumber, config *TraceConfig) (*rpc.Subscription, error) {
    from, err := api.blockByNumber(ctx, start)
    if err != nil {
        return nil, err
    }
    to, err := api.blockByNumber(ctx, end)
    if err != nil {
        return nil, err
    }
    if from.Number().Cmp(to.Number()) &gt;= 0 {
        return nil, fmt.Errorf("end block (#%d) needs to come after start block (#%d)", end, start)
    }
    notifier, supported := rpc.NotifierFromContext(ctx)
    if !supported {
        return &amp;rpc.Subscription{}, rpc.ErrNotificationsUnsupported
    }
    sub := notifier.CreateSubscription()
    resCh := api.traceChain(from, to, config, notifier.Closed())
    go func() {
        for result := // TraceChain returns the structured logs created during the execution of EVM
        // between two blocks (excluding start) and returns them as a JSON object.
        range resCh {
            notifier.Notify(sub.ID, result)
        }
    }()
    return sub, nil
}
