</code></pre> Source code <p> <pre><code>func (api *API) TraceTransaction(ctx context.Context, hash common.Hash, config *TraceConfig) (interface{}, error) {
    found, _, blockHash, blockNumber, index, err := api.backend.GetTransaction(ctx, hash)
    if err != nil {
        return nil, ethapi.NewTxIndexingError()
    }
    if !found {
        return nil, errTxNotFound
    }
    if blockNumber == 0 {
        return nil, errors.New("genesis is not traceable")
    }
    reexec := defaultTraceReexec
    if config != nil &amp;&amp; config.Reexec != nil {
        reexec = *config.Reexec
    }
    block, err := api.blockByNumberAndHash(ctx, rpc.BlockNumber(blockNumber), blockHash)
    if err != nil {
        return nil, err
    }
    msg, vmctx, statedb, release, err := api.backend.StateAtTransaction(ctx, block, int(index), reexec)
    if err != nil {
        return nil, err
    }
    defer release()
    txctx := &amp;Context{BlockHash: blockHash, BlockNumber: block.Number(), TxIndex: int(index), TxHash: hash}
    return api.traceTx(ctx, msg, txctx, vmctx, statedb, config)
}// TraceTransaction returns the structured logs created during the execution of EVM
// and returns them as a JSON object.
